<script module lang="ts">
/**
 * Radio or checkbox options as cards with room for a description (`design/components/choice-card.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/choice-card.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  Icon,
  agentMember,
  joinSlot,
  roveRadio,
  watchEffect,
  type IconRole,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/choice-card.module.css'

export interface ChoiceCardOption {
  value: string
  label: string
  description?: string
  icon?: IconRole
  disabled?: boolean
}

export interface ChoiceCardProps {
  /**
   * The maximum column count. The container resolves the actual count on Grid's scale
   * (`grid.md`).
   */
  columns?: 1 | 2 | 3
  defaultValue?: string | string[]
  disabled?: boolean
  /**
   * The group's accessible name (`aria-label` on the root).
   */
  label: string
  mode: 'single' | 'multiple'
  onChange?: ((value: string) => void) | ((values: string[]) => void)
  /**
   * Items render from data (Radio's law).
   */
  options: ChoiceCardOption[]
  value?: string | string[]
}
</script>

<script lang="ts">
let {
  columns = 1,
  defaultValue,
  disabled = false,
  label: labelOwn,
  mode,
  onChange,
  options,
  value,
}: ChoiceCardProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ disabled: disabled, label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
// svelte-ignore state_referenced_locally
let singleMirror = $state(mode === 'single' ? (defaultValue as string | undefined) : undefined)
// svelte-ignore state_referenced_locally
let multipleMirror = $state(
  mode === 'multiple' ? ((defaultValue as string[] | undefined) ?? []) : [],
)
let grid = $state<HTMLElement | null>(null)
const chosen = $derived(
  mode === 'single' ? ((value as string | undefined) ?? singleMirror) : undefined,
)
const checkedValues = $derived(
  mode === 'multiple' ? ((value as string[] | undefined) ?? multipleMirror) : ([] as string[]),
)
const isChecked = $derived((optionValue: string) =>
  mode === 'single' ? chosen === optionValue : checkedValues.includes(optionValue),
)
const stop = $derived(
  chosen ?? options.find((option) => !(disabled || option.disabled === true))?.value,
)
const select = $derived(
  (next: string) =>
    next !== chosen &&
    ((singleMirror = next), (onChange as ((...args: any[]) => unknown) | undefined)?.(next), true),
)
const toggle = $derived((optionValue: string, checked: boolean) =>
  ((next: string[]) => (
    (multipleMirror = next),
    (onChange as ((...args: any[]) => unknown) | undefined)?.(next)
  ))(
    options
      .filter((option) =>
        option.value === optionValue ? checked : checkedValues.includes(option.value),
      )
      .map((option) => option.value),
  ),
)
const chooseAll = $derived((chosen: readonly string[]) =>
  ((next: string[]) =>
    next.length === checkedValues.length && next.every((each) => checkedValues.includes(each))
      ? undefined
      : ((multipleMirror = next), (onChange as ((...args: any[]) => unknown) | undefined)?.(next)))(
    options
      .filter((option) =>
        disabled || option.disabled === true
          ? checkedValues.includes(option.value)
          : chosen.includes(option.value),
      )
      .map((option) => option.value),
  ),
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'ChoiceCard',
    element: () => grid,
    state: () => ({
      value: mode === 'single' ? (chosen === undefined ? [] : [chosen]) : checkedValues,
      options: options.map((option) => ({
        id: option.value,
        label: option.label,
        ...(option.disabled === true ? { disabled: true } : {}),
      })),
      mode: mode,
      disabled: disabled,
    }),
    actions: {
      choose: {
        argument: 'ids',
        run: (value) =>
          (() => {
            if (mode === 'multiple') return chooseAll(value)
            const [only] = value
            if (only === undefined || value.length !== 1)
              throw new Error('A single-choice ChoiceCard takes exactly one id.')
            select(only)
          })(),
      },
    },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if mode === 'single'
    }<div
      bind:this={grid}
      class={styles.grid}
      role="radiogroup"
      aria-label={label}
      data-columns={String(columns)}
      data-disabled={(disabled) ? '' : undefined}
      data-member="choice-card"
      >{#each options as option, index (option.value)
        }<label
          class={styles.option}
          data-state={(isChecked(option.value)) ? 'checked' : 'unchecked'}
          data-disabled={(disabled || option.disabled === true) ? '' : undefined}
          ><button
            class={styles.control}
            type="button"
            role="radio"
            value={option.value}
            aria-checked={isChecked(option.value)}
            disabled={disabled || option.disabled === true}
            aria-labelledby={`${uid}-option-${index}-label`}
            aria-describedby={(option.description !== undefined) ? `${uid}-option-${index}-description` : undefined}
            data-state={(isChecked(option.value)) ? 'checked' : 'unchecked'}
            data-disabled={(disabled || option.disabled === true) ? '' : undefined}
            tabindex={(option.value === stop ? 0 : -1) as never}
            onclick={() => { select(option.value) }}
            onkeydown={(event) => { event.key === 'Enter' ? event.preventDefault() : roveRadio(event, (next) => select(next)) }}
          ></button
          >{#if option.icon !== undefined
            }<span class={styles.icon}><Icon name={option.icon} size="md" /></span
          >{/if
          }<span class={styles.label} id={`${uid}-option-${index}-label`}>{option.label}</span
          >{#if option.description !== undefined
            }<span class={styles.description} id={`${uid}-option-${index}-description`}
              >{option.description
            }</span
          >{/if
          }{#if isChecked(option.value)
            }<span class={styles.glyph}><Icon name="confirm" size="md" /></span
          >{/if
        }</label
      >{/each
    }</div
  >{:else
    }<div
      bind:this={grid}
      class={styles.grid}
      role="group"
      aria-label={label}
      data-columns={String(columns)}
      data-disabled={(disabled) ? '' : undefined}
      data-member="choice-card"
      >{#each options as option, index (option.value)
        }<label
          class={styles.option}
          data-state={(isChecked(option.value)) ? 'checked' : 'unchecked'}
          data-disabled={(disabled || option.disabled === true) ? '' : undefined}
          ><button
            class={styles.control}
            type="button"
            role="checkbox"
            value={option.value}
            aria-checked={isChecked(option.value)}
            disabled={disabled || option.disabled === true}
            aria-labelledby={`${uid}-option-${index}-label`}
            aria-describedby={(option.description !== undefined) ? `${uid}-option-${index}-description` : undefined}
            data-state={(isChecked(option.value)) ? 'checked' : 'unchecked'}
            data-disabled={(disabled || option.disabled === true) ? '' : undefined}
            onclick={() => { toggle(option.value, !(isChecked(option.value))) }}
            onkeydown={(event) => { if (event.key === 'Enter') event.preventDefault() }}
          ></button
          >{#if option.icon !== undefined
            }<span class={styles.icon}><Icon name={option.icon} size="md" /></span
          >{/if
          }<span class={styles.label} id={`${uid}-option-${index}-label`}>{option.label}</span
          >{#if option.description !== undefined
            }<span class={styles.description} id={`${uid}-option-${index}-description`}
              >{option.description
            }</span
          >{/if
          }{#if isChecked(option.value)
            }<span class={styles.glyph}><Icon name="confirm" size="md" /></span
          >{/if
        }</label
      >{/each
    }</div
  >{/if
}{/if
}{@render joined.end?.()}
